let cleanupCurrent = null;

export function initSectionParallax({ root, lenis } = {}) {
  destroySectionParallax();
  if (!root) return;

  const images = [...root.querySelectorAll(".section .feature_image_holder .feature_image")];
  if (!images.length) return;

  const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
  const originalStyles = images.map((image) => ({
    image,
    translate: image.style.translate,
    willChange: image.style.willChange,
  }));
  let frame = 0;

  const update = () => {
    frame = 0;
    if (reducedMotion.matches) {
      images.forEach((image) => { image.style.translate = "0 0"; });
      return;
    }

    const viewportHeight = window.innerHeight || 1;
    images.forEach((image) => {
      const holder = image.closest(".feature_image_holder");
      const section = image.closest(".section");
      if (!holder || !section) return;

      const bounds = section.getBoundingClientRect();
      const imageHeight = image.getBoundingClientRect().height;
      const overflow = Math.max(0, (imageHeight - holder.clientHeight) / 2);
      const progress = Math.min(1, Math.max(0, (viewportHeight - bounds.top) / (viewportHeight + bounds.height)));
      const offset = (progress - 0.5) * 2 * overflow;
      image.style.translate = `0 ${offset.toFixed(2)}px`;
      image.style.willChange = "translate";
    });
  };

  const scheduleUpdate = () => {
    if (!frame) frame = requestAnimationFrame(update);
  };
  const onMotionPreferenceChange = () => scheduleUpdate();

  window.addEventListener("scroll", scheduleUpdate, { passive: true });
  window.addEventListener("resize", scheduleUpdate, { passive: true });
  lenis?.on?.("scroll", scheduleUpdate);
  reducedMotion.addEventListener("change", onMotionPreferenceChange);
  scheduleUpdate();

  cleanupCurrent = () => {
    cancelAnimationFrame(frame);
    window.removeEventListener("scroll", scheduleUpdate);
    window.removeEventListener("resize", scheduleUpdate);
    lenis?.off?.("scroll", scheduleUpdate);
    reducedMotion.removeEventListener("change", onMotionPreferenceChange);
    originalStyles.forEach(({ image, translate, willChange }) => {
      image.style.translate = translate;
      image.style.willChange = willChange;
    });
  };
}

export function destroySectionParallax() {
  cleanupCurrent?.();
  cleanupCurrent = null;
}
