import { initBarba } from "./modules/barba.js";
import { installUnderlineLinkStyles } from "./modules/text-animations.js";
import { initThreeScene } from "./modules/three-scene.js";
import { destroyLinkHover, initLinkHover } from "./modules/link-hover.js";
import { destroyLogoJitter, initLogoJitter } from "./modules/logo-jitter.js";
import { initLogoLottieControls, prepareLogoHost } from "./modules/logo-lottie-controls.js";
import { initScrollingBanner } from "./modules/scrolling-banner.js";
import { startLenisRaf } from "./modules/lenis-raf.js";
import { destroySectionNavigation, initSectionNavigation } from "./modules/section-navigation.js";
import { destroySectionParallax, initSectionParallax } from "./modules/section-parallax.js";
import { destroyFloatingRegister, hideFloatingRegister, initFloatingRegister, prepareFloatingRegister } from "./modules/floating-register.js";
import { domReady } from "./utils/dom-ready.js";

const app = { three: null, barba: null, lenis: null };
installUnderlineLinkStyles();
installNavCurrentStyles();
prepareLogoHost(document);

function installNavCurrentStyles() {
  const style = document.createElement("style");
  style.textContent = `
    .nav { isolation: isolate; }
    .nav::before {
      content: "";
      position: fixed;
      inset: 0 0 auto;
      height: 180px;
      z-index: -1;
      pointer-events: none;
      opacity: var(--nav-gradient-opacity, 0);
      background: linear-gradient(to bottom, #edff00 0%, rgba(237, 255, 0, 0.82) 38%, rgba(237, 255, 0, 0) 100%);
      transform: translate3d(0, var(--nav-gradient-y, 0px), 0);
      will-change: transform, opacity;
    }
    .nav a.cta.w--current {
      background-color: var(--colour--other-blue);
      color: var(--colour--other-yellow);
    }
  `;
  document.head.appendChild(style);
}

async function boot() {
  await domReady();
  app.lenis = window.lenis || (typeof lenis !== "undefined" ? lenis : null);
  startLenisRaf(app.lenis);
  initScrollingBanner(document, app.lenis);
  // This mount lives outside Barba's container and survives every navigation.
  app.three = initThreeScene({ mount: document.querySelector("[data-three-canvas]"), lenis: app.lenis });
  app.barba = initBarba({
    onEnter: runPageSetup,
    onLeave: runPageTeardown,
    onBeforeLeave: ({ container }) => hideFloatingRegister(container),
    onTransitionStart: () => {
      app.lenis?.stop();
    },
    onTransitionComplete: () => {
      app.lenis?.scrollTo(0, { immediate: true });
      app.lenis?.start();
      app.three?.syncScroll();
    },
  });

  if (!app.barba) {
    const container = document.querySelector("[data-barba='container']");
    await runPageSetup({ container });
  }
}

async function runPageSetup({ container, namespace, html, transition = false }) {
  if (!container) return;
  const pageNamespace = String(namespace || container.dataset.barbaNamespace || "page").toLowerCase();
  const setup = async () => {
    container.dataset.pageActive = "true";
    document.body.dataset.page = pageNamespace;
    app.three?.setPage({
      capsule: container.classList.contains("cap2"),
      scrollTarget: container.querySelector("#origin"),
    });
    const Webflow = window.Webflow;
    Webflow?.destroy?.();
    prepareLogoHost(document);
    const incoming = html ? new DOMParser().parseFromString(html, "text/html") : document;
    if (html) {
      const pageId = incoming.documentElement.getAttribute("data-wf-page");
      if (pageId) document.documentElement.setAttribute("data-wf-page", pageId);
    }
    syncNavCurrent(incoming);
    initSectionNavigation({
      nav: document.querySelector(".nav"),
      sectionsRoot: container,
      ticker: document.querySelector(".scrolling_banner"),
      lenis: app.lenis,
    });
    initSectionParallax({ root: container, lenis: app.lenis });
    prepareFloatingRegister(container);
    Webflow?.ready?.();
    Webflow?.require?.("ix2")?.init?.();
    initLinkHover(container);
    initFloatingRegister(container);
    initLogoLottieControls(document);
    initLogoJitter(document);
    container.querySelectorAll("[data-year]").forEach((element) => {
      element.textContent = String(new Date().getFullYear());
    });
  };

  await setup();
  if (!transition) window.ScrollTrigger?.refresh();
}

function syncNavCurrent(page) {
  const activeHref = page.querySelector(".nav a.w--current[href]")?.getAttribute("href");
  document.querySelectorAll(".nav a[href]").forEach((link) => {
    const active = Boolean(activeHref && link.getAttribute("href") === activeHref);
    link.classList.toggle("w--current", active);
    if (active) link.setAttribute("aria-current", "page");
    else link.removeAttribute("aria-current");
  });
}

function runPageTeardown({ container }) {
  if (!container) return;
  destroySectionNavigation();
  destroySectionParallax();
  destroyLinkHover(container);
  destroyFloatingRegister(container);
  destroyLogoJitter(container);
  delete container.dataset.pageActive;
}

boot().catch((error) => {
  console.error("[base] Setup failed.", error);
});

export { app };
