const STYLE_ID = "scrolling-banner-ticker-style";
const instances = new WeakMap();

export function initScrollingBanner(root = document, lenis = null) {
  root.querySelectorAll(".scrolling_banner").forEach((banner) => {
    if (instances.has(banner)) return;
    const inner = banner.querySelector(":scope > .scrolling_banner_inner");
    if (!inner) return;

    installStyles();
    const instance = createTicker(banner, inner, lenis);
    instances.set(banner, instance);
    instance.start();
  });
}

export function setScrollingBannerText(banner, text) {
  if (!banner) return;
  const instance = instances.get(banner);
  if (instance) {
    instance.setText(text);
    return;
  }
  const heading = banner.querySelector(".scrolling_banner_inner h5");
  if (heading) heading.textContent = text;
}

function createTicker(banner, inner, lenis) {
  const track = document.createElement("div");
  const group = document.createElement("div");
  track.className = "scrolling_banner_track";
  group.className = "scrolling_banner_group";
  group.append(inner);
  track.append(group);
  banner.append(track);
  banner.classList.add("scrolling_banner--ticker");

  const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
  const resizeObserver = new ResizeObserver(rebuild);
  let animation = null;
  let duplicate = null;
  let textTransitions = [];
  let transitionId = 0;
  let rateFrame = 0;
  let currentRate = 1;
  let targetRate = 1;
  let previousScroll = lenis?.scroll ?? window.scrollY;
  let previousScrollTime = performance.now();
  let lastScrollAt = 0;

  function rebuild() {
    if (reducedMotion.matches) {
      animation?.cancel();
      animation = null;
      duplicate?.remove();
      duplicate = null;
      cancelAnimationFrame(rateFrame);
      rateFrame = 0;
      return;
    }

    const itemWidth = inner.getBoundingClientRect().width;
    const containerWidth = banner.getBoundingClientRect().width;
    if (!itemWidth || !containerWidth) return;

    duplicate?.remove();
    duplicate = null;
    while (group.children.length > 1) group.lastElementChild.remove();

    while (group.getBoundingClientRect().width < containerWidth + itemWidth) {
      const copy = inner.cloneNode(true);
      copy.setAttribute("aria-hidden", "true");
      group.append(copy);
    }

    duplicate = group.cloneNode(true);
    duplicate.setAttribute("aria-hidden", "true");
    track.append(duplicate);

    if (!animation) {
      const distance = group.getBoundingClientRect().width;
      const speed = Math.max(1, Number.parseFloat(banner.dataset.tickerSpeed) || 55);
      const duration = distance / speed * 1000;
      animation = track.animate(
        [{ transform: "translate3d(0, 0, 0)" }, { transform: "translate3d(-50%, 0, 0)" }],
        { duration, iterations: Infinity, easing: "linear" },
      );
      animation.playbackRate = currentRate;
    }
  }

  function setText(text) {
    const heading = inner.querySelector("h5");
    if (!heading || heading.textContent === text) return;
    const currentTransition = ++transitionId;
    textTransitions.forEach((transition) => transition.cancel());
    textTransitions = [];
    if (reducedMotion.matches) {
      heading.textContent = text;
      rebuild();
      return;
    }

    const outgoing = [...track.querySelectorAll(".scrolling_banner_inner h5")].map((item) => item.animate(
      [{ clipPath: "inset(0 0 0 0)" }, { clipPath: "inset(0 0 0 100%)" }],
      { duration: 160, easing: "cubic-bezier(.7, 0, .3, 1)" },
    ));
    textTransitions = outgoing;
    Promise.all(outgoing.map((transition) => transition.finished)).then(() => {
      if (currentTransition !== transitionId) return;
      heading.textContent = text;
      rebuild();
      textTransitions = [...track.querySelectorAll(".scrolling_banner_inner h5")].map((item) => item.animate(
        [{ clipPath: "inset(0 100% 0 0)" }, { clipPath: "inset(0 0 0 0)" }],
        { duration: 260, easing: "cubic-bezier(.2, .7, .2, 1)" },
      ));
    }).catch(() => {});
  }

  function easePlaybackRate(now) {
    rateFrame = 0;
    if (!animation || reducedMotion.matches) return;
    if (now - lastScrollAt > 90) targetRate = 1;

    const elapsed = Math.min(48, Math.max(1, now - (easePlaybackRate.previousTime || now)));
    easePlaybackRate.previousTime = now;
    const blend = 1 - Math.exp(-elapsed / 100);
    currentRate += (targetRate - currentRate) * blend;

    if (Math.abs(targetRate - currentRate) < 0.015 && targetRate === 1) {
      currentRate = 1;
      animation.playbackRate = currentRate;
      return;
    }

    animation.playbackRate = currentRate;
    rateFrame = requestAnimationFrame(easePlaybackRate);
  }

  function onLenisScroll(event) {
    const currentScroll = Number.isFinite(event?.scroll) ? event.scroll : (lenis?.scroll ?? window.scrollY);
    const now = performance.now();
    const elapsed = Math.max(now - previousScrollTime, 16);
    const scrollVelocity = clamp((currentScroll - previousScroll) / elapsed * 1000, -2400, 2400);
    targetRate = clamp(1 + scrollVelocity / 420, -3.2, 6.7);
    lastScrollAt = now;
    previousScroll = currentScroll;
    previousScrollTime = now;
    if (!rateFrame && animation && !reducedMotion.matches) rateFrame = requestAnimationFrame(easePlaybackRate);
  }

  return {
    start() {
      resizeObserver.observe(banner);
      reducedMotion.addEventListener("change", rebuild);
      lenis?.on?.("scroll", onLenisScroll);
      document.fonts?.ready.then(rebuild);
      rebuild();
    },
    rebuild,
    setText,
  };
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function installStyles() {
  if (document.getElementById(STYLE_ID)) return;
  const style = document.createElement("style");
  style.id = STYLE_ID;
  style.textContent = `
    .scrolling_banner--ticker { overflow: hidden; }
    .scrolling_banner--ticker .scrolling_banner_track,
    .scrolling_banner--ticker .scrolling_banner_group {
      display: flex;
      align-items: center;
      flex: none;
      width: max-content;
    }
    .scrolling_banner--ticker .scrolling_banner_track { will-change: transform; }
    .scrolling_banner--ticker .scrolling_banner_group {
      gap: 3rem;
      padding-right: 3rem;
    }
    .scrolling_banner--ticker .scrolling_banner_inner {
      flex: none;
      width: max-content;
      white-space: nowrap;
    }
    .scrolling_banner--ticker .scrolling_banner_inner h5 { white-space: nowrap; }
  `;
  document.head.append(style);
}
