export function startLenisRaf(lenis) {
  if (!lenis) return () => {};

  let frame = 0;
  let quietFrames = 0;

  const schedule = () => {
    if (!frame && !document.hidden) frame = requestAnimationFrame(tick);
  };

  const tick = (time) => {
    frame = 0;
    if (document.hidden) return;

    const previousScroll = lenis.scroll;
    lenis.raf(time);
    const moved = Math.abs(lenis.scroll - previousScroll) > 0.001;
    quietFrames = moved ? 0 : quietFrames + 1;
    if (moved || quietFrames < 3) schedule();
  };

  const onKeyDown = (event) => {
    if (["ArrowDown", "ArrowUp", "PageDown", "PageUp", "Home", "End", " "].includes(event.key)) schedule();
  };
  const onVisibilityChange = () => {
    if (document.hidden) {
      cancelAnimationFrame(frame);
      frame = 0;
      quietFrames = 0;
    } else {
      schedule();
    }
  };

  window.addEventListener("wheel", schedule, { passive: true });
  window.addEventListener("touchstart", schedule, { passive: true });
  window.addEventListener("touchmove", schedule, { passive: true });
  window.addEventListener("scroll", schedule, { passive: true });
  window.addEventListener("keydown", onKeyDown, { passive: true });
  window.addEventListener("click", schedule, { passive: true });
  document.addEventListener("visibilitychange", onVisibilityChange);

  return () => {
    cancelAnimationFrame(frame);
    window.removeEventListener("wheel", schedule);
    window.removeEventListener("touchstart", schedule);
    window.removeEventListener("touchmove", schedule);
    window.removeEventListener("scroll", schedule);
    window.removeEventListener("keydown", onKeyDown);
    window.removeEventListener("click", schedule);
    document.removeEventListener("visibilitychange", onVisibilityChange);
  };
}
