import lottie from "lottie-web/build/player/lottie_svg";

const DEFAULT_OPTIONS = {
  selector: ".hero_logo",
  path: "/logo/OtherHero.json",
  startPercent: 50,
  endPercent: 90,
  startFrame: null,
  endFrame: null,
  easeSeconds: 0.3,
};

const instances = new WeakMap();

export function prepareLogoHost(root = document) {
  root.querySelectorAll?.(DEFAULT_OPTIONS.selector).forEach((container) => {
    container.removeAttribute("data-animation-type");
    container.removeAttribute("data-w-id");
    container.removeAttribute("data-src");
  });
}

export function initLogoLottieControls(root = document, options = {}) {
  const settings = { ...DEFAULT_OPTIONS, ...options };
  root.querySelectorAll?.(settings.selector).forEach((container) => {
    if (instances.has(container)) return;
    const instance = createControlsInstance(container, settings);
    instances.set(container, instance);
    instance.start();
  });
}

export function destroyLogoLottieControls(root = document) {
  root.querySelectorAll?.(DEFAULT_OPTIONS.selector).forEach((container) => {
    instances.get(container)?.destroy();
    instances.delete(container);
  });
}

function createControlsInstance(container, settings) {
  let animationItem = null;
  let frameId = 0;
  let destroyed = false;
  let progress = 0;
  let targetProgress = 0;
  let lastTime = 0;

  const frameRange = () => {
    const lastFrame = Math.max(animationItem.totalFrames - 1, 0);
    const start = settings.startFrame ?? lastFrame * settings.startPercent / 100;
    const end = settings.endFrame ?? lastFrame * settings.endPercent / 100;
    return [Math.max(0, Math.min(start, lastFrame)), Math.max(0, Math.min(end, lastFrame))];
  };

  const renderFrame = (time) => {
    frameId = 0;
    if (!animationItem || !animationItem.isLoaded || destroyed) return;
    if (lastTime && settings.easeSeconds > 0) {
      const elapsed = Math.min(time - lastTime, 100);
      progress += (targetProgress - progress) * (1 - Math.exp(-elapsed / (settings.easeSeconds * 1000)));
    } else {
      progress = targetProgress;
    }
    lastTime = time;
    if (Math.abs(targetProgress - progress) < 0.0001) progress = targetProgress;
    const [start, end] = frameRange();
    animationItem.goToAndStop(start + progress * (end - start), true);
    container.dispatchEvent(new Event("logo-frame-change"));
    if (progress !== targetProgress) frameId = requestAnimationFrame(renderFrame);
    else lastTime = 0;
  };

  const handlePointerMove = (event) => {
    if (event.pointerType !== "mouse" && event.pointerType !== "pen") return;
    targetProgress = Math.min(Math.max(event.clientX / window.innerWidth, 0), 1);
    if (animationItem?.isLoaded && !frameId) {
      lastTime = performance.now();
      frameId = requestAnimationFrame(renderFrame);
    }
  };

  const start = async () => {
    window.addEventListener("pointermove", handlePointerMove, { passive: true });
    try {
      const response = await fetch(settings.path);
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const animationData = await response.json();
      if (destroyed) return;

      container.replaceChildren();
      animationItem = lottie.loadAnimation({
        container,
        renderer: "svg",
        loop: false,
        autoplay: false,
        animationData,
      });

      if (animationItem.isLoaded) configure();
      else animationItem.addEventListener("DOMLoaded", configure);
    } catch (error) {
      console.error("[logo] Local animation could not be loaded.", error);
    }
  };

  const configure = () => {
    if (!animationItem || destroyed) return;
    animationItem.removeEventListener("DOMLoaded", configure);
    animationItem.pause();
    animationItem.setSubframe(true);

    animationItem.goToAndStop(frameRange()[0], true);
    if (targetProgress !== progress) {
      lastTime = performance.now();
      frameId = requestAnimationFrame(renderFrame);
    }
  };

  const destroy = () => {
    destroyed = true;
    window.removeEventListener("pointermove", handlePointerMove);
    cancelAnimationFrame(frameId);
    animationItem?.destroy();
  };

  return { start, destroy };
}
