import * as THREE from "three";

const BOTTLE_HEIGHT = 4.1;
const BODY_RADIUS = 0.63;
const WALL_THICKNESS = 0.055;
const LIQUID_OVERLAP = 0.012;
const DEFAULT_CORK_LENGTH = 0.42;
const DEFAULT_LIQUID_LEVEL = 0.79268;
const LIQUID_MAX_LEVEL = 0.97;
const RADIAL_SEGMENTS = 64;

// Left half of Plan.svg: recessed underside, flat contact band, then vertical wall.
const BASE_JOIN_HEIGHT = (617.41 - 593.91) / 618.93 * BOTTLE_HEIGHT;
const BASE_CURVES = {
  outer: [
    [[98, 558.41], [46.75, 558.41], [42.51, 617.41], [22.01, 617.41]],
    [[22.01, 617.41], [19.06, 617.41], [16.11, 617.41], [13.16, 617.41]],
    [[13.16, 617.41], [5.94, 617.41], [2, 610.46], [2, 593.91]],
  ],
  inner: [
    [[98, 533.89], [36.02, 533.89], [31.48, 607.41], [21.45, 607.41]],
    [[21.45, 607.41], [12.31, 607.41], [12.48, 602.39], [12.48, 593.91]],
  ],
};

// Traced outer silhouette from src/model/BottleCurve.png, from the contact ring to the mouth.
export const BOTTLE_CURVE_PROFILE = {
  axisX: 199,
  bottomY: 1235,
  bodyX: 10,
  points: [
    [49, 1235], [27, 1213], [10, 1188], [10, 1180],
    [10, 1050], [10, 850], [12, 750], [27, 650], [61, 550],
    [104, 450], [127, 350], [135, 250], [139, 150], [139, 80],
    [135, 70], [130, 58], [134, 45], [140, 35], [142, 23],
    [137, 12], [140, 0],
  ],
};

function traceProfile({ axisX, bottomY, bodyX, points: pixels }) {
  const side = pixels.map(([x, y]) => new THREE.Vector2(
    (axisX - x) / (axisX - bodyX) * BODY_RADIUS,
    (bottomY - y) / bottomY * BOTTLE_HEIGHT,
  ));
  const profile = new THREE.SplineCurve(side).getPoints(100);
  profile.forEach((point) => {
    point.x = Math.max(0, point.x);
    point.y = Math.max(0, point.y);
  });
  return profile;
}

function floorProfile(which, joinRadius, overlap = 0) {
  const endX = which === "outer" ? 2 : 12.48;
  const scale = joinRadius / ((98 - endX) / 96 * BODY_RADIUS);
  const point = ([x, y]) => new THREE.Vector2(
    (98 - x) / 96 * BODY_RADIUS * scale,
    (617.41 - y) / 618.93 * BOTTLE_HEIGHT - overlap,
  );
  return BASE_CURVES[which].flatMap((segment, index) => {
    const curve = new THREE.CubicBezierCurve(...segment.map(point));
    const sampled = curve.getPoints(40);
    return index ? sampled.slice(1) : sampled;
  });
}

function wallAboveJoin(side, radius) {
  return [
    new THREE.Vector2(radius, BASE_JOIN_HEIGHT),
    new THREE.Vector2(radius, BASE_JOIN_HEIGHT + 0.025),
    ...side.filter((point) => point.y > BASE_JOIN_HEIGHT + 0.03),
  ];
}

function sideRadiusAt(side, height) {
  for (let index = 1; index < side.length; index++) {
    if (side[index].y >= height) {
      const before = side[index - 1];
      const mix = (height - before.y) / (side[index].y - before.y);
      return THREE.MathUtils.lerp(before.x, side[index].x, mix);
    }
  }
  return side.at(-1).x;
}

function insetProfile(profile, distance) {
  return profile.map((point, index) => {
    if (point.y < 1.4) return new THREE.Vector2(Math.max(0, point.x - distance), point.y);
    const before = profile[Math.max(0, index - 1)];
    const after = profile[Math.min(profile.length - 1, index + 1)];
    const tangent = after.clone().sub(before).normalize();
    return new THREE.Vector2(
      Math.max(0, point.x - tangent.y * distance),
      point.y + tangent.x * distance,
    );
  });
}

function createLiquidProfile(side, level) {
  const surface = insetProfile(side, WALL_THICKNESS - LIQUID_OVERLAP);
  const floor = floorProfile("inner", sideRadiusAt(surface, BASE_JOIN_HEIGHT), LIQUID_OVERLAP);
  const profile = [...floor];

  for (let index = 1; index < surface.length; index++) {
    if (surface[index].y <= BASE_JOIN_HEIGHT) continue;
    if (surface[index].y >= level) {
      const previous = surface[index - 1];
      const current = surface[index];
      const ratio = (level - previous.y) / (current.y - previous.y);
      profile.push(previous.clone().lerp(current, ratio));
      break;
    }
    profile.push(surface[index]);
  }

  profile.push(new THREE.Vector2(0, level));
  return profile;
}

function getBottleAxis(sourceBottle) {
  if (!sourceBottle) return new THREE.Vector3(0, 1, 0);
  sourceBottle.updateWorldMatrix(true, true);
  const points = [];
  sourceBottle.traverse((mesh) => {
    if (!mesh.isMesh) return;
    const positions = mesh.geometry.getAttribute("position");
    const step = Math.max(1, Math.floor(positions.count / 3000));
    for (let index = 0; index < positions.count; index += step) {
      points.push(new THREE.Vector3().fromBufferAttribute(positions, index).applyMatrix4(mesh.matrixWorld));
    }
  });
  if (!points.length) return new THREE.Vector3(0, 1, 0);

  const centre = points.reduce((sum, point) => sum.add(point), new THREE.Vector3()).divideScalar(points.length);
  const covariance = [0, 0, 0, 0, 0, 0];
  points.forEach((point) => {
    const x = point.x - centre.x;
    const y = point.y - centre.y;
    const z = point.z - centre.z;
    covariance[0] += x * x;
    covariance[1] += x * y;
    covariance[2] += x * z;
    covariance[3] += y * y;
    covariance[4] += y * z;
    covariance[5] += z * z;
  });
  const axis = new THREE.Vector3(0, 1, 0);
  for (let iteration = 0; iteration < 16; iteration++) {
    axis.set(
      covariance[0] * axis.x + covariance[1] * axis.y + covariance[2] * axis.z,
      covariance[1] * axis.x + covariance[3] * axis.y + covariance[4] * axis.z,
      covariance[2] * axis.x + covariance[4] * axis.y + covariance[5] * axis.z,
    ).normalize();
  }
  if (axis.y < 0) axis.negate();
  return axis;
}

function createCork(sourceCork, sourceBottle, height, neckRadius) {
  const diameter = 2 * (neckRadius - WALL_THICKNESS + LIQUID_OVERLAP);
  let cork;
  let baseScaleY = 1;
  let baseHeight = DEFAULT_CORK_LENGTH;
  if (!sourceCork) {
    cork = new THREE.Mesh(
      new THREE.CylinderGeometry(diameter / 2, diameter / 2, 1, 48),
      new THREE.MeshPhysicalMaterial({ color: 0xc5a477, roughness: 1 }),
    );
    cork.name = "Cork";
    baseHeight = 1;
    cork.scale.set(diameter, DEFAULT_CORK_LENGTH, diameter);
  } else {
    sourceCork.updateWorldMatrix(true, false);
    const source = sourceCork.clone(true);
    source.matrix.copy(sourceCork.matrixWorld);
    source.matrix.decompose(source.position, source.quaternion, source.scale);
    cork = new THREE.Group();
    cork.name = "Cork";
    cork.add(source);
    const bounds = new THREE.Box3().setFromObject(cork);
    source.position.sub(bounds.getCenter(new THREE.Vector3()));
    cork.quaternion.setFromUnitVectors(getBottleAxis(sourceBottle), new THREE.Vector3(0, 1, 0));
    const orientedSize = new THREE.Box3().setFromObject(cork).getSize(new THREE.Vector3());
    baseHeight = orientedSize.y;
    baseScaleY = diameter / Math.max(orientedSize.x, orientedSize.z);
    cork.scale.set(baseScaleY, baseScaleY, baseScaleY);
  }

  const setLength = (length) => {
    const nextLength = THREE.MathUtils.clamp(length, 0.2, 0.8);
    cork.scale.y = baseScaleY * nextLength / baseHeight;
    cork.position.y = height - nextLength / 2;
  };
  setLength(DEFAULT_CORK_LENGTH);
  return { mesh: cork, setLength };
}

function createLabelArea() {
  const bottom = 0.23;
  const top = 1.27;
  const rings = 32;
  const radius = BODY_RADIUS + 0.01;
  const vertices = [];
  const uvs = [];
  const indices = [];

  for (let ring = 0; ring <= rings; ring++) {
    const v = ring / rings;
    const y = THREE.MathUtils.lerp(bottom, top, v);
    for (let segment = 0; segment <= RADIAL_SEGMENTS; segment++) {
      const u = segment / RADIAL_SEGMENTS;
      const angle = u * Math.PI * 2;
      vertices.push(Math.sin(angle) * radius, y, Math.cos(angle) * radius);
      uvs.push(u, v);
      if (ring < rings && segment < RADIAL_SEGMENTS) {
        const a = ring * (RADIAL_SEGMENTS + 1) + segment;
        const b = a + RADIAL_SEGMENTS + 1;
        indices.push(a, a + 1, b, a + 1, b + 1, b);
      }
    }
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.Float32BufferAttribute(vertices, 3));
  geometry.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  const mesh = new THREE.Mesh(geometry, new THREE.MeshBasicMaterial({
    color: 0xffffff,
    side: THREE.FrontSide,
    transparent: true,
    opacity: 1,
    depthTest: false,
    depthWrite: false,
    toneMapped: false,
  }));
  mesh.name = "Bottle wrap";
  mesh.renderOrder = 1000;
  return mesh;
}

function createBaseDetails(side, material) {
  const details = new THREE.Group();
  details.name = "Base details";
  const crescentShape = new THREE.Shape();
  crescentShape.moveTo(-0.013, 0);
  crescentShape.quadraticCurveTo(0, 0.012, 0.013, 0);
  crescentShape.quadraticCurveTo(0, 0.005, -0.013, 0);
  const crescentGeometry = new THREE.ExtrudeGeometry(crescentShape, {
    depth: 0.01, bevelEnabled: false, curveSegments: 8,
  });
  crescentGeometry.rotateX(Math.PI / 2);
  const crescents = new THREE.InstancedMesh(crescentGeometry, material, 64);
  const dotRadius = 0.012;
  const dotRadialScale = 0.65;
  const dots = new THREE.InstancedMesh(new THREE.SphereGeometry(dotRadius, 10, 8), material, 18);
  const transform = new THREE.Object3D();
  const heelRadius = 0.525;

  for (let index = 0; index < crescents.count; index++) {
    const angle = index / crescents.count * Math.PI * 2;
    transform.position.set(Math.sin(angle) * (heelRadius - 0.006), 0.006, Math.cos(angle) * (heelRadius - 0.006));
    transform.rotation.set(0, angle, 0);
    transform.scale.set(1.4, 1, 1.4);
    transform.updateMatrix();
    crescents.setMatrixAt(index, transform.matrix);
  }

  for (let group = 0; group < 6; group++) {
    for (let dot = 0; dot < 3; dot++) {
      const index = group * 3 + dot;
      const angle = group / 6 * Math.PI * 2 + (dot - 1) * 0.06;
      const height = (618.93 - 590.43) / 618.93 * BOTTLE_HEIGHT;
      const radius = sideRadiusAt(side, height) - dotRadius * dotRadialScale * 0.55;
      transform.position.set(Math.sin(angle) * radius, height, Math.cos(angle) * radius);
      transform.rotation.set(0, angle, 0);
      transform.scale.set(1, 1, dotRadialScale);
      transform.updateMatrix();
      dots.setMatrixAt(index, transform.matrix);
    }
  }

  details.add(crescents, dots);
  return details;
}

export function createGeneratedBottle({ sourceCork, sourceBottle, profile = BOTTLE_CURVE_PROFILE } = {}) {
  const root = new THREE.Group();
  root.name = "Generated bottle";

  const side = traceProfile(profile);
  const outer = [...floorProfile("outer", BODY_RADIUS), ...wallAboveJoin(side, BODY_RADIUS).slice(1)];
  const innerSide = insetProfile(side, WALL_THICKNESS);
  const innerRadius = BODY_RADIUS - WALL_THICKNESS;
  const inner = [...floorProfile("inner", innerRadius), ...wallAboveJoin(innerSide, innerRadius).slice(1)];
  const glass = new THREE.Mesh(
    new THREE.LatheGeometry([...outer, ...inner.reverse()], RADIAL_SEGMENTS),
    new THREE.MeshPhysicalMaterial(),
  );
  glass.name = "AM Bottle";
  root.add(glass);

  const liquid = new THREE.Mesh(
    new THREE.LatheGeometry(createLiquidProfile(side, LIQUID_MAX_LEVEL * BOTTLE_HEIGHT), RADIAL_SEGMENTS),
    new THREE.MeshPhysicalMaterial(),
  );
  liquid.name = "AM Bottle Liquid";
  root.add(liquid);

  const liquidCap = new THREE.Mesh(new THREE.BufferGeometry(), liquid.material);
  liquidCap.name = "Generated liquid surface";
  root.add(liquidCap);
  const clippingPlane = new THREE.Plane(new THREE.Vector3(0, -1, 0), -1000);
  let liquidLevel = DEFAULT_LIQUID_LEVEL;
  let previousMatrix = null;
  let previousWorldLevel = NaN;
  const surface = insetProfile(side, WALL_THICKNESS - LIQUID_OVERLAP);
  const setLiquidLevel = (value) => {
    liquidLevel = THREE.MathUtils.clamp(value, 0.1, 0.9);
  };

  function updateHorizontalLevel() {
    root.updateWorldMatrix(true, true);
    const worldLevelPoint = root.localToWorld(new THREE.Vector3(0, liquidLevel * BOTTLE_HEIGHT, 0));
    clippingPlane.constant = worldLevelPoint.y;
    liquid.updateWorldMatrix(true, false);
    const matrix = liquid.matrixWorld.elements;
    if (previousMatrix && Math.abs(previousWorldLevel - worldLevelPoint.y) < 1e-5 && matrix.every((value, index) => Math.abs(value - previousMatrix[index]) < 1e-5)) return;
    const localPlane = clippingPlane.clone().applyMatrix4(liquid.matrixWorld.clone().invert());
    const contour = [];
    const localPoints = [];
    const segments = 64;

    for (let index = 0; index < segments; index++) {
      const angle = index / segments * Math.PI * 2;
      const cosine = Math.cos(angle);
      const sine = Math.sin(angle);
      let intersection = null;
      let closest = Infinity;

      for (let profileIndex = 1; profileIndex < surface.length; profileIndex++) {
        const a = surface[profileIndex - 1];
        const b = surface[profileIndex];
        if (a.y < BASE_JOIN_HEIGHT || b.y < BASE_JOIN_HEIGHT) continue;
        const distanceA = localPlane.normal.x * a.x * cosine + localPlane.normal.y * a.y + localPlane.normal.z * a.x * sine + localPlane.constant;
        const distanceB = localPlane.normal.x * b.x * cosine + localPlane.normal.y * b.y + localPlane.normal.z * b.x * sine + localPlane.constant;
        if (distanceA * distanceB > 0 || Math.abs(distanceA - distanceB) < 1e-8) continue;
        const ratio = distanceA / (distanceA - distanceB);
        const point = a.clone().lerp(b, ratio);
        const delta = Math.abs(point.y - liquidLevel * BOTTLE_HEIGHT);
        if (delta < closest) {
          closest = delta;
          intersection = new THREE.Vector3(point.x * cosine, point.y, point.x * sine);
        }
      }

      if (!intersection) continue;
      const worldPoint = liquid.localToWorld(intersection.clone());
      contour.push(new THREE.Vector2(worldPoint.x, worldPoint.z));
      localPoints.push(intersection);
    }

    const triangles = THREE.ShapeUtils.triangulateShape(contour, []);
    const positions = [];
    triangles.forEach((triangle) => triangle.forEach((vertexIndex) => {
      const point = localPoints[vertexIndex];
      positions.push(point.x, point.y, point.z);
    }));
    for (let index = 0; index < positions.length; index += 9) {
      [positions[index + 3], positions[index + 6]] = [positions[index + 6], positions[index + 3]];
      [positions[index + 4], positions[index + 7]] = [positions[index + 7], positions[index + 4]];
      [positions[index + 5], positions[index + 8]] = [positions[index + 8], positions[index + 5]];
    }
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
    geometry.computeVertexNormals();
    liquidCap.geometry.dispose();
    liquidCap.geometry = geometry;
    previousMatrix = matrix.slice();
    previousWorldLevel = worldLevelPoint.y;
  }

  const corkModel = createCork(sourceCork, sourceBottle, BOTTLE_HEIGHT, side.at(-1).x);
  const cork = corkModel.mesh;
  root.add(cork);
  const labelArea = createLabelArea();
  root.add(labelArea);
  const baseDetails = createBaseDetails(side, glass.material);
  root.add(baseDetails);

  return {
    root, glass, liquid, liquidCap, clippingPlane, cork, labelArea, baseDetails,
    setCorkLength: corkModel.setLength,
    setLiquidLevel,
    updateHorizontalLevel,
    get liquidLevel() { return liquidLevel; },
  };
}
