import * as THREE from "three";
import { RoomEnvironment } from "three/examples/jsm/environments/RoomEnvironment.js";
import { GUI } from "three/examples/jsm/libs/lil-gui.module.min.js";
import { HDRLoader } from "three/examples/jsm/loaders/HDRLoader.js";
import { createGeneratedBottle } from "./generated-bottle.js";

const IDLE_DELAY = 1000;
const LOG_PREFIX = "[kujira webgl]";
const STYLE_ID = "kujira-webgl-style";
const DEFAULT_CORK_COLOR = "#b4895d";
const labelBaseScales = new WeakMap();

export function initThreeScene({ mount, lenis = null } = {}) {
  if (!mount) {
    console.warn(`${LOG_PREFIX} No [data-three-canvas] mount found.`);
    return null;
  }

  let renderer;

  try {
    renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
  } catch (error) {
    console.warn(`${LOG_PREFIX} Renderer could not be created.`, error);
    return null;
  }

  const settings = getSceneSettings(mount);
  installWebglStyles();
  const scene = new THREE.Scene();
  const labelOverlayScene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(settings.fov, 1, 0.1, 100);
  const modelGroup = new THREE.Group();
  const timer = new THREE.Timer();
  const hdrLoader = new HDRLoader();
  const pmremGenerator = new THREE.PMREMGenerator(renderer);
  const refractionUniforms = {
    liquidLogoTexture: { value: createEmptyTexture() },
    resolution: { value: new THREE.Vector2(1, 1) },
    logoOffsetY: { value: settings.logoProjectionY },
    backgroundColor: { value: getPageBackgroundColor(mount) },
  };

  camera.position.set(
    settings.cameraPosition.x,
    settings.cameraPosition.y,
    settings.cameraPosition.z,
  );
  camera.lookAt(0, 0, 0);
  const pagePose = { ...settings.pagePoses.home };
  modelGroup.position.set(pagePose.x, pagePose.y, pagePose.z);
  modelGroup.rotation.set(
    THREE.MathUtils.degToRad(pagePose.rx),
    THREE.MathUtils.degToRad(pagePose.ry),
    THREE.MathUtils.degToRad(pagePose.rz),
  );
  modelGroup.scale.setScalar(settings.modelScale);
  scene.add(modelGroup);
  scene.add(new THREE.HemisphereLight(0xffffff, 0x555555, 0.7));

  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = getToneMapping(settings.toneMapping);
  renderer.toneMappingExposure = settings.exposure;
  renderer.autoClear = false;
  renderer.localClippingEnabled = true;
  mount.appendChild(renderer.domElement);

  const mouseTarget = new THREE.Vector2();
  const mouseRotation = new THREE.Vector2();

  let model = null;
  let generatedBottle = null;
  let generatedLabelSource = null;
  let generatedLabelOverlay = null;
  let frameId = null;
  let idleTimer = null;
  let pagePoseTween = null;
  let logoPlane = null;
  let logoCaptureTimeout = 0;
  let logoCapturePending = false;
  let logoPositionDirty = false;
  let bottleParts = null;
  let physicalBackdrop = null;
  let gui = null;
  let selectPoseInGui = null;
  let running = false;
  let disposed = false;
  let capsulePage = false;
  let scrollPoseEnabled = false;
  let scrollPoseTarget = null;
  let pageInitialized = false;
  let scrollProgress = 0;

  const ready = Promise.all([setupEnvironment(), loadLogoPlane(), loadModel()]);

  function getWidth() {
    return mount.clientWidth || window.innerWidth || 1;
  }

  function getHeight() {
    return mount.clientHeight || window.innerHeight || 1;
  }

  function resize() {
    const width = getWidth();
    const height = getHeight();

    camera.aspect = width / height;
    camera.updateProjectionMatrix();
    renderer.setSize(width, height);
    renderer.getDrawingBufferSize(refractionUniforms.resolution.value);
    physicalBackdrop?.update(logoPlane?.userData?.logoTexture?.image, refractionUniforms.backgroundColor.value);
    if (capsulePage || scrollPoseEnabled) syncScroll();
    requestLogoTextureUpdate();
    wake("resize");
  }

  function requestLogoTextureUpdate() {
    if (!logoPlane || disposed) return;
    logoCapturePending = true;
    if (logoPlane.userData.updating || logoCaptureTimeout) return;
    const delay = Math.max(0, 1000 / settings.logoCaptureFps - (performance.now() - logoPlane.userData.lastTextureUpdate));
    logoCaptureTimeout = window.setTimeout(() => {
      logoCaptureTimeout = 0;
      updateLogoTexture();
    }, delay);
  }

  async function updateLogoTexture() {
    if (!logoCapturePending || !logoPlane || disposed) return;
    logoCapturePending = false;

    const svg = logoPlane.userData.logoElement.querySelector("svg");
    const texture = logoPlane.userData.logoTexture;
    const canvas = texture.image;
    const context = logoPlane.userData.logoContext;

    if (!svg || !context) return;
    logoPlane.userData.updating = true;
    logoPlane.userData.lastTextureUpdate = performance.now();
    try {
      const image = await drawLogoToCanvas(svg, logoPlane.userData.logoElement, mount, canvas, context, settings);
      if (!disposed) {
        logoPlane.userData.logoImage = image;
        logoPlane.userData.logoRectKey = getLogoRectKey(logoPlane.userData.logoElement, mount, settings);
        if (bottleParts?.liquidLogoStrength.value > 0) logoPlane.userData.liquidLogo.updateImage(image);
        texture.needsUpdate = true;
        physicalBackdrop?.update(canvas, refractionUniforms.backgroundColor.value);
        wake("logo texture updated");
      }
    } catch (error) {
      console.warn(`${LOG_PREFIX} Logo capture failed.`, error);
    } finally {
      logoPlane.userData.updating = false;
      if (logoCapturePending) requestLogoTextureUpdate();
    }
  }

  function updateLogoPosition() {
    logoPositionDirty = false;
    if (!logoPlane?.userData.logoImage || logoPlane.userData.updating) return;
    const { logoElement, logoImage, logoTexture, logoContext } = logoPlane.userData;
    const rectKey = getLogoRectKey(logoElement, mount, settings);
    if (rectKey === logoPlane.userData.logoRectKey) return;
    drawLogoImage(logoImage, logoElement, mount, logoTexture.image, logoContext, settings);
    logoPlane.userData.logoRectKey = rectKey;
    logoTexture.needsUpdate = true;
    if (bottleParts?.liquidLogoStrength.value > 0) logoPlane.userData.liquidLogo.position();
    physicalBackdrop?.update(logoTexture.image, refractionUniforms.backgroundColor.value);
  }

  function render() {
    if (!running) return;

    timer.update();
    if (logoPositionDirty) updateLogoPosition();
    const delta = Math.min(timer.getDelta(), 0.1);

    if (model) {
      model.rotation.x += settings.intrinsicRotationSpeed.x * delta;
      model.rotation.y += settings.intrinsicRotationSpeed.y * delta;
    }

    mouseRotation.x = THREE.MathUtils.damp(mouseRotation.x, mouseTarget.x, 7, delta);
    mouseRotation.y = THREE.MathUtils.damp(mouseRotation.y, mouseTarget.y, 7, delta);
    const radius = settings.cameraPosition.z;
    camera.position.set(
      radius * Math.sin(mouseRotation.x) * Math.cos(mouseRotation.y),
      radius * Math.sin(mouseRotation.y),
      radius * Math.cos(mouseRotation.x) * Math.cos(mouseRotation.y),
    );
    camera.lookAt(0, 0, 0);
    physicalBackdrop?.position(camera);
    const viewportHeight = 2 * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)) * radius;
    if (scrollPoseEnabled) {
      const { home, capsule } = settings.pagePoses;
      for (const key of ["x", "y", "z", "rx", "ry", "rz"]) {
        pagePose[key] = THREE.MathUtils.lerp(home[key], capsule[key], scrollProgress);
      }
    }
    modelGroup.position.set(
      pagePose.x,
      pagePose.y + (capsulePage || scrollPoseEnabled ? scrollProgress * viewportHeight * settings.scrollTravelVh : 0),
      pagePose.z,
    );
    modelGroup.rotation.set(
      THREE.MathUtils.degToRad(pagePose.rx),
      THREE.MathUtils.degToRad(pagePose.ry),
      THREE.MathUtils.degToRad(pagePose.rz),
    );
    if (generatedBottle?.root.visible) generatedBottle.updateHorizontalLevel();
    const showLabelOverlay = Boolean(generatedLabelSource?.visible && generatedBottle?.root.visible);
    if (generatedLabelSource) generatedLabelSource.visible = false;
    renderer.clear();
    renderer.render(scene, camera);
    if (generatedLabelSource) generatedLabelSource.visible = showLabelOverlay;
    if (generatedLabelSource && generatedLabelOverlay && showLabelOverlay) {
      generatedBottle.root.updateWorldMatrix(true, true);
      generatedLabelOverlay.matrix.copy(generatedLabelSource.matrixWorld);
      generatedLabelOverlay.matrixWorldNeedsUpdate = true;
      generatedLabelOverlay.visible = true;
      renderer.clearDepth();
      renderer.render(labelOverlayScene, camera);
    } else if (generatedLabelOverlay) {
      generatedLabelOverlay.visible = false;
    }
    frameId = window.requestAnimationFrame(render);
  }

  function start(reason) {
    if (running || document.hidden || disposed) return;

    running = true;
    timer.update();
    console.log(`${LOG_PREFIX} rendering started`, { reason });
    render();
  }

  function stop(reason) {
    if (!running) return;

    running = false;
    window.cancelAnimationFrame(frameId);
    frameId = null;
    console.log(`${LOG_PREFIX} rendering stopped`, { reason });
  }

  function wake(reason = "activity", delay = IDLE_DELAY) {
    window.clearTimeout(idleTimer);
    start(reason);
    idleTimer = window.setTimeout(() => stop("idle"), delay);
  }

  function handleActivity(event) {
    if (event.type === "pointermove" && event.pointerType === "mouse") {
      mouseTarget.x = ((event.clientX / window.innerWidth) * 2 - 1) * settings.mouseYawRange;
      mouseTarget.y = (1 - (event.clientY / window.innerHeight) * 2) * settings.mousePitchRange;
    }
    if (event.type === "scroll") {
      syncScroll();
      return;
    }
    wake(event.type);
  }

  function syncScroll(scroll = lenis?.scroll ?? window.scrollY, limit = lenis?.limit) {
    const distance = Math.max(limit ?? document.documentElement.scrollHeight - window.innerHeight, 1);
    const targetTop = scrollPoseTarget
      ? scrollPoseTarget.getBoundingClientRect().top + scroll
      : distance;
    scrollProgress = capsulePage || scrollPoseEnabled
      ? THREE.MathUtils.clamp(scroll / Math.max(targetTop, 1), 0, 1)
      : 0;
    selectPoseInGui?.(scrollPoseEnabled ? (scrollProgress >= 0.5 ? "capsule" : "home") : (capsulePage ? "capsule" : "home"));
    logoPositionDirty = true;
    wake("scroll position");
  }

  function setPage({ capsule = false, scrollTarget = null } = {}) {
    capsulePage = capsule;
    scrollPoseEnabled = Boolean(scrollTarget);
    scrollPoseTarget = scrollPoseEnabled ? scrollTarget : null;
    const target = settings.pagePoses[capsule ? "capsule" : "home"];
    pagePoseTween?.kill();
    if (scrollPoseEnabled) {
      Object.assign(pagePose, settings.pagePoses.home);
    } else if (pageInitialized && window.gsap) {
      pagePoseTween = window.gsap.to(pagePose, {
        ...target,
        duration: 0.7,
        ease: "power2.inOut",
        onUpdate: () => wake("page pose"),
      });
    } else {
      Object.assign(pagePose, target);
    }
    pageInitialized = true;
    syncScroll();
  }

  function onLenisScroll({ scroll, limit }) {
    syncScroll(scroll, limit);
  }

  function handleVisibilityChange() {
    if (document.hidden) {
      window.clearTimeout(idleTimer);
      stop("tab hidden");
      return;
    }

    wake("tab visible");
  }

  async function loadModel() {
    try {
      const generated = createGeneratedBottle();
      bottleParts = createGeneratedMaterials(refractionUniforms);
      if (disposed) {
        disposeModel(generated.root);
        return;
      }
      try {
        generated.labelArea.material.map = await loadLabelTexture("/textures/label.png");
        generated.labelArea.material.needsUpdate = true;
      } catch (error) {
        console.warn(`${LOG_PREFIX} Label texture could not be loaded.`, error);
      }
      generatedLabelSource = generated.labelArea;
      generatedLabelOverlay = generated.labelArea.clone();
      generatedLabelOverlay.matrixAutoUpdate = false;
      generatedLabelOverlay.renderOrder = 0;
      generatedLabelSource.visible = false;
      labelOverlayScene.add(generatedLabelOverlay);
      generatedBottle = generated;
      frameModel(generated.root);
      generated.glass.material = bottleParts.physicalGlassMaterial;
      generated.baseDetails.children.forEach((mesh) => { mesh.material = bottleParts.physicalGlassMaterial; });
      generated.liquid.material = bottleParts.liquidMaterial;
      const liquidCapMaterial = bottleParts.liquidMaterial.clone();
      liquidCapMaterial.onBeforeCompile = bottleParts.liquidMaterial.onBeforeCompile;
      liquidCapMaterial.customProgramCacheKey = bottleParts.liquidMaterial.customProgramCacheKey.bind(bottleParts.liquidMaterial);
      generated.liquidCap.material = liquidCapMaterial;
      bottleParts.liquidMaterial.clippingPlanes = [generated.clippingPlane];
      bottleParts.glassMeshes = [generated.glass, ...generated.baseDetails.children];
      bottleParts.liquidMeshes = [generated.liquid, generated.liquidCap];
      bottleParts.labelMeshes = [generated.labelArea];
      bottleParts.corkMeshes = [generated.cork];
      generated.root.visible = true;
      modelGroup.add(generated.root);
      model = generated.root;
      const setCorkColor = (color) => generated.cork.material.color.set(color);
      setCorkColor(DEFAULT_CORK_COLOR);
      setMeshesVisible(bottleParts.glassMeshes, true);
      setMeshesVisible(bottleParts.liquidMeshes, true);
      setMeshesVisible(bottleParts.labelMeshes, true);
      setMeshesVisible(bottleParts.corkMeshes, true);
      const debugGui = createDebugGui({
        bottleParts,
        modelGroup,
        refractionUniforms,
        setLabelScale,
        settings,
        wake,
        pagePose,
        isCapsulePage: () => capsulePage,
        isScrollPoseEnabled: () => scrollPoseEnabled,
        stopPageTween: () => pagePoseTween?.kill(),
        setGeneratedLiquidLevel: generated.setLiquidLevel,
        generatedLiquidLevel: generated.liquidLevel,
        liquidCapMaterial,
        corkColor: DEFAULT_CORK_COLOR,
        setCorkColor,
        setCorkLength: generated.setCorkLength,
        refreshLiquidLogo: () => {
          if (logoPlane?.userData.logoImage) logoPlane.userData.liquidLogo.updateImage(logoPlane.userData.logoImage);
        },
      });
      gui = debugGui.gui;
      selectPoseInGui = debugGui.selectPose;
      selectPoseInGui(scrollPoseEnabled && scrollProgress >= 0.5 ? "capsule" : (capsulePage ? "capsule" : "home"));
      wake("model loaded");
    } catch (error) {
      console.warn(`${LOG_PREFIX} Generated bottle could not be created.`, error);
    }
  }

  async function loadLogoPlane() {
    const logoElement = document.querySelector(settings.logoSelector);
    if (!logoElement) return;

    const svg = await waitForLogoSvg(logoElement);
    if (!svg || disposed) return;

    try {
      const texture = await createLogoTexture(svg, logoElement, mount, settings);

      const liquidLogo = createLiquidLogoTexture(texture.userData.logoImage, logoElement, mount, settings, bottleParts?.liquidMaterial.roughness ?? 1);
      refractionUniforms.liquidLogoTexture.value = liquidLogo.texture;
      physicalBackdrop = createPhysicalBackdrop(scene);
      physicalBackdrop.update(texture.image, refractionUniforms.backgroundColor.value);
      logoPlane = {
        userData: {
          logoElement,
          logoTexture: texture,
          logoContext: texture.image.getContext("2d"),
          logoImage: texture.userData.logoImage,
          logoRectKey: getLogoRectKey(logoElement, mount, settings),
          liquidLogo,
          lastTextureUpdate: performance.now(),
        },
      };
      logoElement.style.opacity = settings.domLogoOpacity;
      requestLogoTextureUpdate();
      wake("logo texture loaded");
    } catch (error) {
      console.warn(`${LOG_PREFIX} Logo texture could not be created.`, error);
    }
  }

  function setLabelScale(meshes, scale = 1) {
    meshes.forEach((mesh) => {
      if (!labelBaseScales.has(mesh)) labelBaseScales.set(mesh, mesh.scale.clone());
      const base = labelBaseScales.get(mesh);
      mesh.scale.set(base.x * scale, base.y, base.z * scale);
    });
  }

  async function setupEnvironment() {
    const hdriUrl = mount.dataset.threeHdri;

    if (hdriUrl) {
      try {
        const texture = await hdrLoader.loadAsync(hdriUrl);
        const environment = pmremGenerator.fromEquirectangular(texture).texture;
        texture.dispose();
        scene.environment = environment;
        if (settings.showEnvironment) scene.background = environment;
        return;
      } catch (error) {
        console.warn(`${LOG_PREFIX} HDRI could not be loaded; using preset environment.`, error);
      }
    }

    const environment = pmremGenerator.fromScene(
      new RoomEnvironment(),
      getEnvironmentBlur(settings.environment),
    ).texture;
    scene.environment = environment;
  }

  function destroy() {
    window.removeEventListener("resize", resize);
    window.removeEventListener("pointermove", handleActivity);
    if (lenis) lenis.off?.("scroll", onLenisScroll);
    else window.removeEventListener("scroll", handleActivity);
    document.removeEventListener("visibilitychange", handleVisibilityChange);
    document.querySelector(settings.logoSelector)?.removeEventListener("logo-frame-change", requestLogoTextureUpdate);
    window.clearTimeout(idleTimer);
    window.clearTimeout(logoCaptureTimeout);
    pagePoseTween?.kill();
    stop("destroy");
    disposed = true;

    if (generatedBottle) disposeModel(generatedBottle.root);
    physicalBackdrop?.dispose();
    if (logoPlane?.userData?.logoElement) logoPlane.userData.logoElement.style.opacity = String(settings.domLogoOpacity);
    logoPlane?.userData?.logoTexture?.dispose?.();
    logoPlane?.userData?.liquidLogo?.dispose();
    gui?.destroy();
    pmremGenerator.dispose();
    scene.environment?.dispose?.();
    renderer.dispose();
    renderer.domElement.remove();
  }

  window.addEventListener("resize", resize);
  document.querySelector(settings.logoSelector)?.addEventListener("logo-frame-change", requestLogoTextureUpdate);
  window.addEventListener("pointermove", handleActivity, { passive: true });
  if (lenis) lenis.on("scroll", onLenisScroll);
  else window.addEventListener("scroll", handleActivity, { passive: true });
  document.addEventListener("visibilitychange", handleVisibilityChange);
  resize();

  return { ready, setPage, syncScroll, destroy };
}

function installWebglStyles() {
  if (document.getElementById(STYLE_ID)) return;

  const style = document.createElement("style");
  style.id = STYLE_ID;
  style.textContent = `
    [data-three-canvas],
    [data-three-canvas] canvas {
      pointer-events: none;
    }
    body[data-page="capsule 02"] [data-three-canvas] {
      z-index: 4;
      pointer-events: none;
    }
    body[data-page="capsule 02"] [data-three-canvas] canvas {
      pointer-events: none;
    }
  `;
  document.head.appendChild(style);
}

function getSceneSettings(mount) {
  return {
    fov: 45,
    cameraPosition: { x: 0, y: 0, z: 5 },
    pagePoses: {
      home: { x: 0.02, y: 0.78, z: 0, rx: -22, ry: -22, rz: -17 },
      capsule: { x: -1.1, y: 0.93, z: -0.1, rx: -24, ry: 60, rz: 30 },
    },
    mouseYawRange: 0.2,
    mousePitchRange: 0.1,
    scrollTravelVh: 1.1,
    intrinsicRotationSpeed: { x: 0, y: 0 },
    environment: mount.dataset.threeEnv || "studio",
    exposure: readNumber(mount.dataset.threeExposure, 1.15),
    domLogoOpacity: readNumber(mount.dataset.threeDomLogoOpacity, 1),
    logoCaptureFps: readNumber(mount.dataset.threeLogoFps, 15),
    logoTextureScale: readNumber(mount.dataset.threeLogoTextureScale, 1),
    logoTextureMaxWidth: 1536,
    logoTextureMaxHeight: 864,
    logoDepth: readNumber(mount.dataset.threeLogoDepth, -1.4),
    logoSelector: mount.dataset.threeLogoSelector || ".hero_logo",
    modelScale: readNumber(mount.dataset.threeModelScale, 1.5),
    logoProjectionY: readNumber(mount.dataset.threeLogoProjectionY, 0.37),
    showEnvironment: false,
    toneMapping: mount.dataset.threeTone || "filmic",
  };
}

function readNumber(value, fallback) {
  const number = Number.parseFloat(value);
  return Number.isFinite(number) ? number : fallback;
}

function getPageBackgroundColor(mount) {
  const logo = document.querySelector(".hero_logo");
  for (let element = logo?.parentElement || mount.parentElement; element; element = element.parentElement) {
    const color = new THREE.Color();
    const value = getComputedStyle(element).backgroundColor;
    if (value && value !== "transparent" && !/^rgba\([^)]*,\s*0\s*\)$/.test(value)) {
      color.set(value);
      return color;
    }
  }
  return new THREE.Color(0xdcf158);
}

function createEmptyTexture() {
  const texture = new THREE.DataTexture(new Uint8Array([0, 0, 0, 0]), 1, 1, THREE.RGBAFormat);
  texture.needsUpdate = true;
  return texture;
}

function getToneMapping(name) {
  const toneMapping = {
    aces: THREE.ACESFilmicToneMapping,
    filmic: THREE.ACESFilmicToneMapping,
    linear: THREE.LinearToneMapping,
    neutral: THREE.NeutralToneMapping,
    none: THREE.NoToneMapping,
    reinhard: THREE.ReinhardToneMapping,
  };

  return toneMapping[name] ?? toneMapping.filmic;
}

function getEnvironmentBlur(name) {
  return {
    crisp: 0.01,
    neutral: 0.04,
    soft: 0.08,
    studio: 0.03,
  }[name] ?? 0.03;
}

function createGeneratedMaterials(refractionUniforms) {
  const physicalMaterial = new THREE.MeshPhysicalMaterial({
    color: 0x2c2218,
    metalness: 0,
    roughness: 0,
    transmission: 1,
    thickness: 0.91,
    ior: 1.2,
    dispersion: 0.47,
    opacity: 1,
    depthWrite: true,
    side: THREE.FrontSide,
    envMapIntensity: 1,
  });
  const physicalEdgeLight = { value: 0.5 };
  physicalMaterial.onBeforeCompile = (shader) => {
    shader.uniforms.uEdgeLight = physicalEdgeLight;
    shader.fragmentShader = shader.fragmentShader.replace("#include <common>", `
      #include <common>
      uniform float uEdgeLight;
    `).replace("#include <transmission_fragment>", `
      #include <transmission_fragment>
      float edge = pow(1.0 - abs(normal.z), 2.0);
      totalSpecular += vec3(0.9, 0.98, 1.0) * edge * uEdgeLight;
    `);
  };
  const liquidMaterial = new THREE.MeshPhysicalMaterial({
    color: 0x3a2b07,
    metalness: 0,
    roughness: 1,
    envMapIntensity: 1,
    opacity: 1,
    depthWrite: true,
    side: THREE.FrontSide,
  });
  const liquidLogoStrength = { value: 0.63 };
  liquidMaterial.onBeforeCompile = (shader) => {
    shader.uniforms.uLiquidLogoStrength = liquidLogoStrength;
    shader.uniforms.uLiquidLogoTexture = refractionUniforms.liquidLogoTexture;
    shader.uniforms.uLiquidResolution = refractionUniforms.resolution;
    shader.uniforms.uLiquidLogoOffsetY = refractionUniforms.logoOffsetY;
    shader.uniforms.uLiquidBackground = refractionUniforms.backgroundColor;
    shader.fragmentShader = shader.fragmentShader.replace("#include <common>", `
      #include <common>
      uniform float uLiquidLogoStrength;
      uniform sampler2D uLiquidLogoTexture;
      uniform vec2 uLiquidResolution;
      uniform float uLiquidLogoOffsetY;
      uniform vec3 uLiquidBackground;
    `).replace("#include <color_fragment>", `
      #include <color_fragment>
      vec2 liquidUv = gl_FragCoord.xy / uLiquidResolution;
      liquidUv.y = 1.0 - liquidUv.y + uLiquidLogoOffsetY;
      if (uLiquidLogoStrength > 0.0) {
        vec4 liquidLogo = texture2D(uLiquidLogoTexture, liquidUv);
        vec3 liquidBackdrop = mix(uLiquidBackground, liquidLogo.rgb, liquidLogo.a);
        diffuseColor.rgb = mix(diffuseColor.rgb, liquidBackdrop, uLiquidLogoStrength);
      }
    `);
  };
  return {
    physicalGlassMaterial: physicalMaterial,
    physicalEdgeLight,
    liquidMaterial,
    liquidLogoStrength,
    glassMeshes: [],
    liquidMeshes: [],
    labelMeshes: [],
    corkMeshes: [],
  };
}

function createDebugGui({ bottleParts, modelGroup, refractionUniforms, settings, wake, pagePose, isCapsulePage, isScrollPoseEnabled, stopPageTween, setLabelScale, setGeneratedLiquidLevel, generatedLiquidLevel, liquidCapMaterial, corkColor, setCorkColor, setCorkLength, refreshLiquidLogo }) {
  const gui = new GUI({ title: "Bottle / glass" });
  const controls = {
    glass: true,
    physicalRoughness: bottleParts.physicalGlassMaterial.roughness,
    physicalThickness: bottleParts.physicalGlassMaterial.thickness,
    physicalIor: bottleParts.physicalGlassMaterial.ior,
    physicalDispersion: bottleParts.physicalGlassMaterial.dispersion,
    physicalEdgeLight: bottleParts.physicalEdgeLight.value,
    physicalColor: `#${bottleParts.physicalGlassMaterial.color.getHexString()}`,
    liquid: true,
    label: true,
    labelScale: 1,
    cork: true,
    corkColor,
    corkLength: 0.42,
    liquidColor: `#${bottleParts.liquidMaterial.color.getHexString()}`,
    liquidLogoStrength: bottleParts.liquidLogoStrength.value,
    liquidRoughness: bottleParts.liquidMaterial.roughness,
    generatedLiquidLevel,
    rotate: settings.intrinsicRotationSpeed.y !== 0,
    modelScale: modelGroup.scale.x,
    logoOffsetY: refractionUniforms.logoOffsetY.value,
  };

  gui.add(controls, "glass").name("Glass meshes").onChange((visible) => {
    setMeshesVisible(bottleParts.glassMeshes, visible);
    wake("glass visibility");
  });
  gui.add(controls, "liquid").name("Liquid mesh").onChange((visible) => {
    setMeshesVisible(bottleParts.liquidMeshes, visible);
    wake("liquid visibility");
  });
  setMeshesVisible(bottleParts.labelMeshes, controls.label);
  setMeshesVisible(bottleParts.corkMeshes, controls.cork);
  gui.add(controls, "label").name("Label").onChange((visible) => {
    setMeshesVisible(bottleParts.labelMeshes, visible);
    wake("label visibility");
  });
  gui.add(controls, "labelScale", 0.9, 1.2, 0.005).name("Label scale").onChange((value) => {
    setLabelScale(bottleParts.labelMeshes, value);
    wake("label scale");
  });
  gui.add(controls, "cork").name("Cork").onChange((visible) => {
    setMeshesVisible(bottleParts.corkMeshes, visible);
    wake("cork visibility");
  });
  gui.addColor(controls, "corkColor").name("Cork colour").onChange((value) => {
    setCorkColor(value);
    wake("cork colour");
  });
  gui.add(controls, "corkLength", 0.2, 0.8, 0.01).name("Cork length").onChange((value) => {
    setCorkLength(value);
    wake("cork length");
  });
  const liquidFolder = gui.addFolder("Liquid");
  liquidFolder.add(controls, "generatedLiquidLevel", 0.1, 0.9, 0.01).name("Generated fill level").onChange((value) => {
    setGeneratedLiquidLevel(value);
    wake("generated liquid level");
  });
  liquidFolder.addColor(controls, "liquidColor").name("Colour").onChange((value) => {
    bottleParts.liquidMaterial.color.set(value);
    liquidCapMaterial.color.set(value);
    wake("liquid colour");
  });
  liquidFolder.add(controls, "liquidLogoStrength", 0, 1, 0.01).name("Logo through liquid").onChange((value) => {
    if (value > 0 && bottleParts.liquidLogoStrength.value === 0) refreshLiquidLogo();
    bottleParts.liquidLogoStrength.value = value;
    wake("liquid logo strength");
  });
  liquidFolder.add(controls, "liquidRoughness", 0, 1, 0.01).name("Roughness").onChange((value) => {
    bottleParts.liquidMaterial.roughness = value;
    liquidCapMaterial.roughness = value;
    refractionUniforms.liquidLogoTexture.value.userData.setRoughness?.(value);
    wake("liquid roughness");
  });
  gui.add(controls, "rotate").name("Auto rotate").onChange((enabled) => {
    settings.intrinsicRotationSpeed.y = enabled ? 0.26 : 0;
    wake("auto rotate");
  });
  gui.add(controls, "modelScale", 0.2, 2.5, 0.01).name("Model scale").onChange((value) => {
    modelGroup.scale.setScalar(value);
    wake("model scale");
  });
  const poseControls = { pose: isCapsulePage() ? "capsule" : "home" };
  const poseFolder = gui.addFolder("Bottle pose");
  const poseSelector = poseFolder.add(poseControls, "pose", { Home: "home", "Capsule 02": "capsule" }).name("Editing pose");
  const poseValueControllers = [];
  const selectPose = (page) => {
    if (!settings.pagePoses[page]) return;
    poseControls.pose = page;
    Object.assign(poseControls, settings.pagePoses[page]);
    poseSelector.updateDisplay();
    poseValueControllers.forEach((controller) => controller.updateDisplay());
  };
  poseSelector.onChange(selectPose);
  for (const [key, label, min, max, step] of [
    ["x", "Position X", -2, 2, 0.01],
    ["y", "Position Y", -2, 2, 0.01],
    ["z", "Position Z", -2, 2, 0.01],
    ["rx", "Rotation X", -180, 180, 1],
    ["ry", "Rotation Y", -180, 180, 1],
    ["rz", "Rotation Z", -180, 180, 1],
  ]) {
    poseControls[key] = settings.pagePoses[poseControls.pose][key];
    const controller = poseFolder.add(poseControls, key, min, max, step).name(label).onChange((value) => {
      const page = poseControls.pose;
      settings.pagePoses[page][key] = value;
      stopPageTween();
      if (isScrollPoseEnabled()) {
        wake("scroll pose control");
      } else if (isCapsulePage() === (page === "capsule")) {
        pagePose[key] = value;
        wake("page pose control");
      }
    });
    poseValueControllers.push(controller);
  }
  selectPose(poseControls.pose);
  poseFolder.close();
  gui.add(controls, "logoOffsetY", -0.5, 0.5, 0.005).name("Logo projection height").onChange((value) => {
    refractionUniforms.logoOffsetY.value = value;
    wake("logo projection height");
  });

  const physicalFolder = gui.addFolder("Physical glass");
  physicalFolder.addColor(controls, "physicalColor").name("Colour").onChange((value) => {
    bottleParts.physicalGlassMaterial.color.set(value);
    wake("physical glass colour");
  });
  physicalFolder.add(controls, "physicalEdgeLight", 0, 2, 0.01).name("Edge light").onChange((value) => {
    bottleParts.physicalEdgeLight.value = value;
    wake("physical edge light");
  });
  for (const [key, label, min, max, property] of [
    ["physicalRoughness", "Roughness", 0, 1, "roughness"],
    ["physicalThickness", "Thickness", 0, 2, "thickness"],
    ["physicalIor", "IOR", 1, 2, "ior"],
    ["physicalDispersion", "Dispersion", 0, 1, "dispersion"],
  ]) {
    physicalFolder.add(controls, key, min, max, 0.01).name(label).onChange((value) => {
      bottleParts.physicalGlassMaterial[property] = value;
      wake(`physical ${property}`);
    });
  }
  gui.close();
  return { gui, selectPose };
}

function setMeshesVisible(meshes, visible) {
  meshes.forEach((mesh) => {
    mesh.visible = visible;
  });
}

async function loadLabelTexture(url) {
  const texture = await new THREE.TextureLoader().loadAsync(url);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.wrapS = THREE.RepeatWrapping;
  texture.offset.x = 0.5;
  texture.anisotropy = 4;
  return texture;
}

function createPhysicalBackdrop(scene) {
  const canvas = document.createElement("canvas");
  const context = canvas.getContext("2d");
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.generateMipmaps = false;
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;
  const material = new THREE.MeshBasicMaterial({ map: texture, toneMapped: false });
  const geometry = new THREE.PlaneGeometry(1, 1);
  const mesh = new THREE.Mesh(geometry, material);
  mesh.visible = true;
  mesh.renderOrder = -1;
  mesh.onBeforeRender = (renderer) => {
    const isTransmissionPass = renderer.getRenderTarget() !== null;
    material.colorWrite = isTransmissionPass;
    material.depthWrite = isTransmissionPass;
  };
  scene.add(mesh);

  const direction = new THREE.Vector3();
  return {
    mesh,
    update(source, color) {
      if (!source) return;
      if (canvas.width !== source.width || canvas.height !== source.height) {
        canvas.width = source.width;
        canvas.height = source.height;
      }
      context.fillStyle = color.getStyle();
      context.fillRect(0, 0, canvas.width, canvas.height);
      context.drawImage(source, 0, 0);
      texture.needsUpdate = true;
    },
    position(camera) {
      const distance = 8;
      camera.getWorldDirection(direction);
      mesh.position.copy(camera.position).addScaledVector(direction, distance);
      mesh.quaternion.copy(camera.quaternion);
      const height = 2 * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)) * distance;
      mesh.scale.set(height * camera.aspect, height, 1);
    },
    dispose() {
      scene.remove(mesh);
      geometry.dispose();
      material.dispose();
      texture.dispose();
    },
  };
}

function waitForLogoSvg(element) {
  const existing = element.querySelector("svg");
  if (existing) return Promise.resolve(existing);

  return new Promise((resolve) => {
    const observer = new MutationObserver(() => {
      const svg = element.querySelector("svg");
      if (!svg) return;

      observer.disconnect();
      resolve(svg);
    });

    observer.observe(element, { childList: true, subtree: true });
    window.setTimeout(() => {
      observer.disconnect();
      resolve(element.querySelector("svg"));
    }, 5000);
  });
}

async function createLogoTexture(svg, logoElement, mount, settings) {
  const canvas = document.createElement("canvas");
  const context = canvas.getContext("2d");
  resizeLogoCanvas(canvas, mount, settings);
  const logoImage = await drawLogoToCanvas(svg, logoElement, mount, canvas, context, settings);

  const texture = new THREE.CanvasTexture(canvas);
  texture.userData.logoImage = logoImage;
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.generateMipmaps = false;
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.anisotropy = 1;
  texture.premultiplyAlpha = true;
  texture.needsUpdate = true;
  return texture;
}

async function drawLogoToCanvas(svg, logoElement, mount, canvas, context, settings) {
  resizeLogoCanvas(canvas, mount, settings);

  const clone = svg.cloneNode(true);
  const logoRect = getLogoPixelRect(logoElement, mount, settings);
  clone.setAttribute("xmlns", "http://www.w3.org/2000/svg");
  clone.setAttribute("width", String(logoRect.width));
  clone.setAttribute("height", String(logoRect.height));
  inlineSvgPaint(svg, clone);
  clone.style.filter = "";
  clone.querySelectorAll('filter[id^="logo-jitter-"]').forEach((filter) => filter.remove());
  clone.querySelectorAll('[filter^="url(#logo-jitter-"]').forEach((element) => element.removeAttribute("filter"));

  const svgText = new XMLSerializer().serializeToString(clone);
  const blob = new Blob([svgText], { type: "image/svg+xml" });
  const url = URL.createObjectURL(blob);

  try {
    const image = await loadImage(url);
    drawLogoImage(image, logoElement, mount, canvas, context, settings);
    return image;
  } finally {
    URL.revokeObjectURL(url);
  }
}

function drawLogoImage(image, logoElement, mount, canvas, context, settings) {
  const rect = getLogoPixelRect(logoElement, mount, settings);
  context.clearRect(0, 0, canvas.width, canvas.height);
  context.drawImage(image, rect.x, rect.y, rect.width, rect.height);
}

function createLiquidLogoTexture(initialImage, logoElement, mount, settings, initialRoughness) {
  const canvas = document.createElement("canvas");
  const context = canvas.getContext("2d");
  const blurredImage = document.createElement("canvas");
  const blurredContext = blurredImage.getContext("2d");
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.generateMipmaps = false;
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.premultiplyAlpha = true;
  let image = initialImage;
  let roughness = initialRoughness;

  function position() {
    resizeLogoCanvas(canvas, mount, settings);
    drawLogoImage(roughness > 0 ? blurredImage : image, logoElement, mount, canvas, context, settings);
    texture.needsUpdate = true;
  }

  function refreshBlur() {
    blurredImage.width = image.naturalWidth;
    blurredImage.height = image.naturalHeight;
    blurredContext.clearRect(0, 0, blurredImage.width, blurredImage.height);
    blurredContext.filter = roughness > 0 ? `blur(${18 * roughness}px)` : "none";
    blurredContext.drawImage(image, 0, 0);
    blurredContext.filter = "none";
    position();
  }

  function setRoughness(value) {
    roughness = value;
    refreshBlur();
  }

  texture.userData.setRoughness = setRoughness;
  refreshBlur();
  return {
    texture,
    position,
    updateImage(nextImage) {
      image = nextImage;
      refreshBlur();
    },
    dispose() { texture.dispose(); },
  };
}

function getLogoRectKey(logoElement, mount, settings) {
  const rect = getLogoPixelRect(logoElement, mount, settings);
  return `${rect.x},${rect.y},${rect.width},${rect.height}`;
}

function getLogoTextureMultiplier(mount, settings) {
  const rect = mount.getBoundingClientRect();
  return Math.min(
    Math.min(window.devicePixelRatio || 1, 2) * settings.logoTextureScale,
    settings.logoTextureMaxWidth / Math.max(rect.width, 1),
    settings.logoTextureMaxHeight / Math.max(rect.height, 1),
  );
}

function resizeLogoCanvas(canvas, mount, settings) {
  const rect = mount.getBoundingClientRect();
  const multiplier = getLogoTextureMultiplier(mount, settings);
  const width = Math.max(1, Math.round(rect.width * multiplier));
  const height = Math.max(1, Math.round(rect.height * multiplier));

  if (canvas.width !== width || canvas.height !== height) {
    canvas.width = width;
    canvas.height = height;
  }
}

function getLogoPixelRect(logoElement, mount, settings) {
  const logoRect = logoElement.getBoundingClientRect();
  const mountRect = mount.getBoundingClientRect();
  const multiplier = getLogoTextureMultiplier(mount, settings);

  return {
    x: Math.round((logoRect.left - mountRect.left) * multiplier),
    y: Math.round((logoRect.top - mountRect.top) * multiplier),
    width: Math.max(1, Math.round(logoRect.width * multiplier)),
    height: Math.max(1, Math.round(logoRect.height * multiplier)),
  };
}

function inlineSvgPaint(sourceSvg, cloneSvg) {
  const sourceElements = [sourceSvg, ...sourceSvg.querySelectorAll("*")];
  const cloneElements = [cloneSvg, ...cloneSvg.querySelectorAll("*")];

  sourceElements.forEach((source, index) => {
    const clone = cloneElements[index];
    if (!clone) return;

    const style = window.getComputedStyle(source);
    const fill = source.getAttribute("fill");
    const stroke = source.getAttribute("stroke");

    if (!fill || fill === "currentColor") {
      clone.setAttribute("fill", style.fill || style.color);
    }

    if (stroke === "currentColor") {
      clone.setAttribute("stroke", style.stroke || style.color);
    }
  });
}

function loadImage(src) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = reject;
    image.src = src;
  });
}

function frameModel(root) {
  const box = new THREE.Box3().setFromObject(root);
  const size = box.getSize(new THREE.Vector3());
  const center = box.getCenter(new THREE.Vector3());
  const maxAxis = Math.max(size.x, size.y, size.z) || 1;
  const targetSize = 2.8;

  root.position.sub(center);
  root.scale.multiplyScalar(targetSize / maxAxis);
}

function disposeModel(root) {
  const geometries = new Set();
  const materials = new Set();
  const textures = new Set();

  root.traverse((child) => {
    if (child.geometry) geometries.add(child.geometry);

    const entries = Array.isArray(child.material) ? child.material : [child.material];
    entries.filter(Boolean).forEach((material) => {
      materials.add(material);
      Object.values(material).forEach((value) => {
        if (value?.isTexture) textures.add(value);
      });
    });
  });

  textures.forEach((texture) => texture.dispose());
  materials.forEach((material) => material.dispose());
  geometries.forEach((geometry) => geometry.dispose());
}
