const DURATION = 0.28;
const LOG_PREFIX = "[base lifecycle]";

export function transition({ onEnter, onLeave, onBeforeLeave, onStart, onComplete } = {}) {
  let releaseLeave = () => {};
  let nextReady = Promise.resolve();

  return {
    name: "transition",
    sync: true,
    async once({ next }) {
      console.log(LOG_PREFIX, "transition once -> run setup", getContainerContext(next));
      await onEnter?.(getPageContext(next));
    },
    before({ current, next }) {
      console.log(LOG_PREFIX, "transition before", getTransitionContext(current, next));
      current.container.dataset.pageLeaving = "true";
      onBeforeLeave?.(getPageContext(current));
      delete next.container.dataset.pageLeaving;
      stackContainers(current.container, next.container);
      window.scrollTo(0, 0);
      nextReady = new Promise((resolve) => {
        releaseLeave = resolve;
      });
    },
    async leave({ current }) {
      await nextReady;
      onStart?.(getPageContext(current));
      await fade(current.container, 0);
    },
    async enter({ next }) {
      try {
        await onEnter?.(getPageContext(next, { transition: true }));
      } finally {
        releaseLeave();
      }
      await fade(next.container, 1);
    },
    async after({ current, next }) {
      resetContainer(current.container);
      resetContainer(next.container);
      window.scrollTo(0, 0);
      await onLeave?.(getPageContext(current));
      window.ScrollTrigger?.refresh();
      onComplete?.(getPageContext(next));
    },
  };
}

function fade(container, opacity) {
  const gsap = window.gsap;
  if (gsap) {
    return gsap.to(container, {
      opacity,
      duration: DURATION,
      ease: "power1.inOut",
      overwrite: true,
    });
  }

  return new Promise((resolve) => {
    container.style.transition = `opacity ${DURATION}s ease-in-out`;
    requestAnimationFrame(() => {
      container.style.opacity = String(opacity);
      window.setTimeout(resolve, DURATION * 1000);
    });
  });
}

function stackContainers(current, next) {
  const scrollY = window.scrollY || window.pageYOffset || 0;
  current.style.position = "fixed";
  current.style.top = `${-scrollY}px`;
  current.style.left = "0";
  current.style.width = "100%";
  current.style.zIndex = "1";

  next.style.position = "fixed";
  next.style.top = "0";
  next.style.left = "0";
  next.style.width = "100%";
  next.style.zIndex = "2";
  next.style.opacity = "0";
}

function resetContainer(container) {
  const properties = ["position", "top", "left", "width", "zIndex", "opacity", "transition"];
  properties.forEach((property) => { container.style[property] = ""; });
  delete container.dataset.pageLeaving;
}

function getTransitionContext(current, next) {
  return { current: getContainerContext(current), next: getContainerContext(next) };
}

function getContainerContext(page) {
  return {
    namespace: getNamespaceFromPage(page),
    connected: Boolean(page?.container?.isConnected),
    className: page?.container?.className || "",
  };
}

function getPageContext(page, options = {}) {
  return {
    container: page?.container || null,
    html: page?.html,
    namespace: getNamespaceFromPage(page),
    transition: Boolean(options.transition),
  };
}

function getNamespaceFromPage(page) {
  return String(page?.namespace || page?.container?.dataset?.barbaNamespace || "page")
    .trim()
    .toLowerCase();
}
